#!/bin/bash
# fail2ban/deploy.sh - Deploy fail2ban (jail.d layout) for SSH + Nginx + UFW.
#
# Run as root from a clone of this repository (lib/common.sh is required):
#   SSH_PORT=48825 bash fail2ban/deploy.sh   # port provided (phase2 does this)
#   bash fail2ban/deploy.sh                  # port detected from running sshd
#
# What it deploys:
#   /etc/fail2ban/jail.d/00-default.local     shared defaults (UFW banaction, ...)
#   /etc/fail2ban/jail.d/01-ignoreip.local    generated by update-cloudflare-ips.sh
#   /etc/fail2ban/jail.d/10-sshd.local        rendered with the SSH port
#   /etc/fail2ban/jail.d/20-nginx.local       nginx jails
#   /etc/fail2ban/jail.d/30-recidive.local    repeat-offender escalation
#   /etc/fail2ban/filter.d/*                  custom filters
#   /usr/local/bin/update-cloudflare-ips.sh   + monthly refresh cron

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
source "$SCRIPT_DIR/../lib/common.sh"

require_root

# ── SSH port: environment override, else the running sshd's effective value ──
if [ -z "${SSH_PORT:-}" ]; then
    SSH_PORT="$(sshd -T 2>/dev/null | awk '$1=="port"{print $2; exit}')" || true
fi
if ! [[ "${SSH_PORT:-}" =~ ^[0-9]+$ ]] || [ "$SSH_PORT" -lt 1 ] || [ "$SSH_PORT" -gt 65535 ]; then
    die "Invalid SSH port '${SSH_PORT:-}'. Provide SSH_PORT=<1-65535> or make sure sshd is running."
fi

echo ""
echo "============================================"
echo "  fail2ban Deployment for Xray+Nginx+UFW"
echo "============================================"
echo "  [sshd] jail port: $SSH_PORT"

# ── [1/6] Prerequisites ─────────────────────────────────────────────
msg_step "1/6: Prerequisites"
if ! command -v fail2ban-client &>/dev/null; then
    msg_info "Installing fail2ban..."
    apt update && apt install -y fail2ban
fi
command -v ufw &>/dev/null || die "ufw not found - the ban action depends on it. Deploy UFW first."

# File-backend jails refuse to start when their logpath is missing.
for logfile in /nginx/logs/access.log /nginx/logs/error.log; do
    if [ ! -f "$logfile" ]; then
        msg_warn "$logfile not found - creating an empty file so the jails can start."
        mkdir -p /nginx/logs
        touch "$logfile"
    fi
done

# ── [2/6] Jail configuration (jail.d layout) ────────────────────────
msg_step "2/6: Deploy jail.d and filters"

# A monolithic jail.local from an older deployment would fight the jail.d
# files (fail2ban reads both). Park it out of the way.
if [ -f /etc/fail2ban/jail.local ]; then
    mv /etc/fail2ban/jail.local /etc/fail2ban/jail.local.pre-jaild.bak
    msg_warn "Legacy /etc/fail2ban/jail.local moved to jail.local.pre-jaild.bak"
fi

mkdir -p /etc/fail2ban/jail.d
for f in 00-default.local 20-nginx.local 30-recidive.local; do
    install -o root -g root -m 644 "$SCRIPT_DIR/jail.d/$f" "/etc/fail2ban/jail.d/$f"
    msg_ok "Deployed jail.d/$f"
done

render_template "$SCRIPT_DIR/jail.d/10-sshd.local.template" \
    /etc/fail2ban/jail.d/10-sshd.local \
    "SSH_PORT=$SSH_PORT"
chown root:root /etc/fail2ban/jail.d/10-sshd.local
chmod 644 /etc/fail2ban/jail.d/10-sshd.local
msg_ok "Deployed jail.d/10-sshd.local (port = $SSH_PORT)"

for filter in "$SCRIPT_DIR"/filter.d/*.conf "$SCRIPT_DIR"/filter.d/*.local; do
    [ -f "$filter" ] || continue
    install -o root -g root -m 644 "$filter" "/etc/fail2ban/filter.d/$(basename "$filter")"
    msg_ok "Deployed filter.d/$(basename "$filter")"
done

# ── [3/6] Cloudflare IP updater (owns 01-ignoreip.local + nginx geo) ─
msg_step "3/6: Cloudflare IP updater"
install -o root -g root -m 700 "$SCRIPT_DIR/update-cloudflare-ips.sh" \
    /usr/local/bin/update-cloudflare-ips.sh
msg_ok "Installed /usr/local/bin/update-cloudflare-ips.sh"
# Generates jail.d/01-ignoreip.local (and refreshes the nginx geo file).
# A failure aborts the deployment on purpose: fail2ban must never start
# without the Cloudflare ranges in ignoreip.
/usr/local/bin/update-cloudflare-ips.sh

# ── [4/6] Configuration test ────────────────────────────────────────
msg_step "4/6: Test configuration and filters"
fail2ban-client -t || die "fail2ban configuration test failed - fix the errors above and re-run."
msg_ok "Configuration test passed"

declare -A FILTER_LOGS=(
    ["nginx-sslerror"]="/nginx/logs/error.log"
    ["nginx-path-scan"]="/nginx/logs/access.log"
    ["nginx-4xx-flood"]="/nginx/logs/access.log"
    ["nginx-bad-request"]="/nginx/logs/access.log"
    ["nginx-protocol-probe"]="/nginx/logs/access.log"
    ["nginx-scanner-ua"]="/nginx/logs/access.log"
)
for filter in "${!FILTER_LOGS[@]}"; do
    filter_file="/etc/fail2ban/filter.d/${filter}.conf"
    log_file="${FILTER_LOGS[$filter]}"
    [ -f "$filter_file" ] || continue
    if [ -s "$log_file" ]; then
        msg_info "fail2ban-regex: $filter vs $log_file"
        result=$(fail2ban-regex "$log_file" "$filter_file" 2>&1) || true
        echo "    $(echo "$result" | grep -oP 'Lines: \K.*' || echo 'parse ok, no summary')"
    else
        msg_info "Filter $filter deployed (log empty, regex test skipped)"
    fi
done

# ── [5/6] Monthly Cloudflare IP refresh cron ────────────────────────
msg_step "5/6: Monthly Cloudflare IP update cron"
CRON_LINE="0 3 1 * * /usr/local/bin/update-cloudflare-ips.sh >> /var/log/cf-ip-update.log 2>&1"
{
    crontab -l 2>/dev/null | grep -v "update-cloudflare-ips" || true
    echo "$CRON_LINE"
} | crontab -
msg_ok "Cron installed: 1st of each month, 03:00"

# ── [6/6] Enable and start ──────────────────────────────────────────
msg_step "6/6: Enable and start fail2ban"
systemctl enable fail2ban
systemctl restart fail2ban
sleep 2

echo ""
echo "============================================"
echo "  Deployment Complete"
echo "============================================"
echo ""
echo "Active jails:"
fail2ban-client status
echo ""
echo "--- Useful commands ---"
echo ""
echo "  fail2ban-client status                      # all jails"
echo "  fail2ban-client status sshd                 # one jail"
echo "  fail2ban-client set sshd unbanip 1.2.3.4    # manual unban"
echo "  tail -f /var/log/fail2ban.log               # live log"
echo "  ufw status numbered                         # UFW rules incl. bans"
echo "  /usr/local/bin/update-cloudflare-ips.sh     # refresh CF ranges now"
echo ""
echo "  Permanent safe-list entries: /etc/fail2ban/ignoreip.custom"
echo "  (one entry per line; applied by the updater, kept on every refresh)"
echo ""
